interface Captured {
  method: string;
  url: URL;
  apiKey: string | null;
}

/** Permissive candidate payloads: every wave7 schema accepts at least
 * one of these (verified across all 16 modules — object schemas take
 * {}, array schemas [], and envelope schemas like the fiat history
 * { data: [...] } carry a required empty array under data/rows/list).
 * The harness serves them in order and stops at the first that parses. */
const CANDIDATE_PAYLOADS: unknown[] = [{}, [], { data: [] }, { rows: [] }, { list: [] }];

/** Run one row: serve permissive candidates until the method resolves,
 * capture the outgoing request, and return it. */
async function runRow(row: Row): Promise<Captured> {
  let captured: Captured | undefined;
  let payload: unknown = CANDIDATE_PAYLOADS[0];
  server.use(
    http.all(`*${row.path}`, ({ request }) => {
      captured = {
        method: request.method,
        url: new URL(request.url),
        apiKey: request.headers.get('x-mbx-apikey'),
      };
      return HttpResponse.json(payload as Record<string, unknown> | Array<unknown>);
    }),
  );
  const resource = new row.cls(http_()) as Record<string, (args?: unknown) => Promise<unknown>>;
  let lastError: unknown;
  for (const candidate of CANDIDATE_PAYLOADS) {
    payload = candidate;
    try {
      await resource[row.method](row.args);
      break;
    } catch (err) {
      // This candidate did not satisfy the response schema — try the
      // next shape. If every candidate fails, the response side is
      // genuinely broken and the row must surface the last error.
      lastError = err;
    }
  }
  if (!captured) {
    throw new Error(`no request captured for ${row.method}: ${String(lastError)}`);
  }
  return captured;
}

describe('FiatResource — request contracts (Wave 5/6 generated surface)', () => {
  for (const row of FiatResource_ROWS) {
    it(`${row.method} -> ${row.verb} ${row.path}`, async () => {
      const captured = await runRow(row);
      expect(captured.method).toBe(row.verb);
      expect(captured.url.pathname).toBe(row.path);
      for (const [key, value] of Object.entries(row.args ?? {})) {
        expect(captured.url.searchParams.get(key), `${key} must be serialized into the query string`).toBe(String(value));
      }
      if (row.auth === 'signed') {
        expect(captured.url.searchParams.get('signature'), 'SIGNED routes carry an HMAC signature').toBeTruthy();
        expect(captured.url.searchParams.get('timestamp'), 'SIGNED routes carry a timestamp').toBeTruthy();
        expect(captured.url.searchParams.get('recvWindow'), 'SIGNED routes carry recvWindow').toBeTruthy();
      }
      expect(captured.apiKey, 'non-public routes carry X-MBX-APIKEY').toBe('k');
    });
  }
});

